input.command:
cd /home/user/rork-app && echo "=== SECTION 12: 6 PRODUCTION PROMPTS via public chat endpoint ===" && echo "" && PROMPTS=(
"1. Audit the loading problem in this chat and explain the root cause."
"2. Diagnose why member registration from the landing page is failing."
"3. Diagnose why reels crash after several minutes."
"4. Deploy an approved code change."
"5. Show the current status of an existing worker task."
"6. Explain the IVX production architecture."
)
for i in 0 1 2 3 4 5; do
  PROMPT="${PROMPTS[$i]}"
  echo "--- PROMPT $((i+1)): $PROMPT ---"
  RESULT=$(curl -sS -X POST -H "Content-Type: application/json" -d "{\"message\":\"$PROMPT\",\"roomId\":\"main-room\"}" -w "\n---HTTP %{http_code} | %{time_total}s---" https://api.ivxholding.com/public/chat 2>&1)
  echo "$RESULT" | bun -e "
const raw = require('fs').readFileSync('/dev/stdin','utf8');
const lines = raw.split('\n---HTTP');
const body = lines[0];
const meta = lines[1] || '';
try {
  const d = JSON.parse(body);
  console.log('  source:', d.source || 'N/A');
  console.log('  model:', d.model || 'N/A');
  console.log('  answer (first 300 chars):', (d.answer || '').slice(0, 300));
  console.log('  rateLimitRemaining:', d.rateLimitRemaining);
} catch(e) { console.log('  PARSE ERROR:', body.slice(0, 200)); }
console.log('  HTTP' + meta);
" 2>&1
  echo ""
  sleep 1
done

